@app.cell(hide_code=True)
def _():
    # Illustration of the detection step. Static screenshots from the
    # laboratory's own feature-finding output; nothing here is recomputed and
    # no value anywhere on the page is derived from this trace.
    def _build_detection_panel():
        """Analytical-complexity panel plus the declaration of the three layers."""

        # --- REVISAR 1 -------------------------------------------------------
        # Feature counts as reported by the laboratory pipeline for one run.
        N_MAJOR, N_MEDIUM, N_MINOR = 165, 413, 1075
        # The stratification rule is the laboratory's. Replace this string with
        # the actual criterion (relative TIC intensity? area percentile?
        # S/N band?). Do not publish the vague wording.
        STRATUM_RULE = "intensity strata as defined by the laboratory feature-finding step"
        # --- REVISAR 2 -------------------------------------------------------
        # One sentence, literally true, about where this trace comes from.
        # Needs the group's sign-off before publication: the screenshots carry
        # no identifiers, but the retention-time pattern and the absolute
        # intensities are a fingerprint of a real, non-public sample.
        TRACE_SOURCE = (
            "an anonymised total ion chromatogram from a GC-QTOF migration run "
            "at E4CE Lab (University of Alicante)"
        )
        # ---------------------------------------------------------------------

        N_FEATURES = N_MAJOR + N_MEDIUM + N_MINOR

        PANEL_CSS = """
        <style>
        .gx-det { margin-top:20px; }
        /* Layer switcher: one figure, three views. No JavaScript -- hidden
           radios plus sibling selectors, so it survives static export. */
        .gx-det-tabs { margin:14px 0 6px; }
        .gx-det-tabs > input { position:absolute; width:1px; height:1px; opacity:0; }
        .gx-det-bar { display:flex; gap:6px; flex-wrap:wrap; margin-bottom:9px; }
        .gx-det-bar label { cursor:pointer; padding:7px 12px; border:1px solid #dce2df; border-radius:5px; background:#fffdf9;
          font:11px/1.4 ui-monospace,SFMono-Regular,Menlo,monospace; text-transform:uppercase; letter-spacing:.06em; color:#61737b; user-select:none; }
        .gx-det-bar label:hover { border-color:#126b78; color:#126b78; }
        .gx-det-stage { background:#fffdf9; border:1px solid #dce2df; border-radius:7px; padding:11px 13px 9px; }
        .gx-det-view { display:none; margin:0; }
        .gx-det-view img { width:100%; display:block; border-radius:4px; aspect-ratio:980/552; }
        .gx-det-cap { display:flex; gap:10px; align-items:baseline; margin-top:8px; min-height:36px; font-size:12px; color:#61737b; }
        .gx-det-cap b { flex:0 0 auto; font:11px/1.4 ui-monospace,SFMono-Regular,Menlo,monospace; text-transform:uppercase; letter-spacing:.06em; color:#126b78; }
        #gxdet-2:checked ~ .gx-det-stage .gx-det-cap b { color:#aa6916; }
        #gxdet-0:checked ~ .gx-det-stage .gx-det-view:nth-of-type(1),
        #gxdet-1:checked ~ .gx-det-stage .gx-det-view:nth-of-type(2),
        #gxdet-2:checked ~ .gx-det-stage .gx-det-view:nth-of-type(3) { display:block; }
        #gxdet-0:checked ~ .gx-det-bar label[for="gxdet-0"],
        #gxdet-1:checked ~ .gx-det-bar label[for="gxdet-1"] { background:#126b78; border-color:#126b78; color:#fff; }
        #gxdet-2:checked ~ .gx-det-bar label[for="gxdet-2"] { background:#aa6916; border-color:#aa6916; color:#fff; }
        #gxdet-0:focus-visible ~ .gx-det-bar label[for="gxdet-0"],
        #gxdet-1:focus-visible ~ .gx-det-bar label[for="gxdet-1"],
        #gxdet-2:focus-visible ~ .gx-det-bar label[for="gxdet-2"] { outline:3px solid #6550a8; outline-offset:2px; }

        .gx-split { margin:26px 0 20px; border:2px dashed #c9a86a; border-radius:9px; background:#fdf6e9; padding:15px 18px; text-align:center; }
        .gx-split-tag { font:11px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace; text-transform:uppercase; letter-spacing:.1em; color:#915811; }
        .gx-split strong { display:block; font:400 23px/1.25 Georgia,"Iowan Old Style",serif; color:#253b43; margin:7px 0 5px; letter-spacing:-.3px; }
        .gx-split p { font-size:13px; color:#6b5634; max-width:720px; margin:0 auto!important; }

        .gx-scale { display:grid; grid-template-columns:1fr auto 1fr; gap:14px; align-items:stretch; margin:16px 0 6px; }
        .gx-scale-box { border:1px solid #dce2df; border-top:3px solid #126b78; border-radius:7px; padding:13px 15px; background:#fffdf9; min-width:0; }
        .gx-scale-box:last-child { border-top-color:#6550a8; background:#faf8fd; }
        .gx-scale-box em { font-style:normal; font:11px/1.5 ui-monospace,monospace; text-transform:uppercase; letter-spacing:.06em; color:#61737b; }
        .gx-scale-box b { display:block; font:400 40px/1.1 ui-monospace,monospace; color:#126b78; letter-spacing:-1.6px; margin:5px 0 3px; }
        .gx-scale-box:last-child b { color:#6550a8; }
        .gx-scale-box span { display:block; font-size:12px; color:#61737b; }
        .gx-scale-vs { align-self:center; font:11px/1.5 ui-monospace,monospace; text-transform:uppercase; letter-spacing:.1em; color:#915811; }

        .gx-layers { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:10px; margin:16px 0 4px; }
        .gx-layer { border:1px solid #dce2df; border-top:3px solid #61737b; border-radius:6px; padding:12px 14px; background:#f7f6f1; font-size:12px; color:#40555c; }
        .gx-layer:nth-child(3) { border-top-color:#6550a8; background:#eeeafb; border-color:#d9cfee; }
        .gx-layer b { display:block; font:10px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace; text-transform:uppercase; letter-spacing:.06em; color:#61737b; margin-bottom:3px; }
        .gx-layer strong { display:block; font-size:14px; color:#253b43; margin-bottom:5px; }
        .gx-layer:nth-child(3) strong { color:#513d90; }
        .gx-layer-q { display:block; margin-top:8px; padding-top:8px; border-top:1px solid #0000001a; font-style:italic; color:#513d90; }
        .gx-layer-tag { display:inline-block; margin-top:7px; padding:2px 6px; border-radius:3px; font:10px/1.5 ui-monospace,monospace; background:#ffffffb0; border:1px solid #d7ded9; color:#61737b; }
        .gx-layer:nth-child(3) .gx-layer-tag { border-color:#cfc3ea; color:#6550a8; }
        @media(max-width:800px) {
          .gx-layers { grid-template-columns:1fr; }
          .gx-scale { grid-template-columns:1fr; }
          .gx-scale-vs { justify-self:center; }
        }
        </style>
        """

        # tab label, caption label, base64, caption
        PANELS = (
            ("TIC only", "Measured", "",
             "Total ion chromatogram of the extract. This is what a report normally reproduces: a trace, not a list of compounds."),
            (f"+ {N_MEDIUM} medium", "+ Medium", "",
             f"The same trace with {N_MEDIUM:,} medium-intensity features marked. Each marker is a deconvoluted mass trace with a retention time, not yet an identity."),
            (f"+ {N_MINOR:,} minor", "+ Minor", "",
             f"And {N_MINOR:,} minor features. The flat region after 50 min is not empty; it sits below a threshold somebody chose."),
        )

        def switcher_html():
            inputs = "".join(
                f'<input type="radio" name="gxdet" id="gxdet-{i}"{" checked" if i == 0 else ""}>'
                for i in range(len(PANELS))
            )
            bar = "".join(
                f'<label for="gxdet-{i}">{tab}</label>' for i, (tab, _, _, _) in enumerate(PANELS)
            )
            views = "".join(
                f'<figure class="gx-det-view"><img alt="Total ion chromatogram, retention time 8 to 62 min, '
                f'{tab}" src="data:image/webp;base64,{b64}">'
                f'<figcaption class="gx-det-cap"><b>{cap_label}</b><span>{caption}</span></figcaption></figure>'
                for tab, cap_label, b64, caption in PANELS
            )
            return (f'<div class="gx-det-tabs">{inputs}'
                    f'<div class="gx-det-bar" role="group" aria-label="Feature layers">{bar}</div>'
                    f'<div class="gx-det-stage">{views}</div></div>')

        def section(features, provenance):
            n_assignments = len(features)
            n_confirmed = provenance["n_standard_confirmed"]
            n_library = n_assignments - n_confirmed
            return PANEL_CSS + f'''<div class="gx gx-det">

              <div class="gx-kicker">A · What the instrument actually sees</div>
              <h2 style="margin:13px 0 0">One run, {N_FEATURES:,} resolved features.</h2>
              <p class="gx-small" style="margin-top:9px;max-width:940px;font-size:14px;color:#40555c">
                A single migration extract, deconvoluted, resolves {N_MAJOR} major,
                {N_MEDIUM} medium and {N_MINOR:,} minor features ({STRATUM_RULE}).
                Not one of them is a compound. Lowering the stratum does not add chemistry to the sample;
                it moves the line an operator drew between signal and baseline. Any identification table
                in this field begins on the far side of that decision.</p>
              {switcher_html()}
              <p class="gx-small">Switch the layers above: one figure, one run, three reporting thresholds —
                not three experiments. Axis labels as captured, in Spanish: retention time in minutes, TIC intensity.</p>

              <div class="gx-split">
                <div class="gx-split-tag">Different dataset · analytical context only</div>
                <strong>This GC-QTOF trace is not the source of the {n_assignments} assignments analysed below.</strong>
                <p>It is {TRACE_SOURCE}, shown to illustrate the complexity of a real migration run.
                  The identity experiment on this page uses a separate, published case study. The two are
                  placed together because they are the same kind of measurement — never because they are
                  the same measurement.</p>
              </div>

              <div class="gx-kicker">B · What gets reported and carried downstream</div>
              <h2 style="margin:13px 0 0">{n_assignments} reported GC–MS assignments.</h2>
              <p class="gx-small" style="margin-top:9px;max-width:940px;font-size:14px;color:#40555c">
                The reproducible case this notebook works with is FCM2018: {n_assignments} assignments
                curated from Tables 2–3 of Galmán Graíño et al. (2018), <span class="gx-mono">doi:10.3390/polym10070802</span>.
                {n_confirmed} were confirmed against an injected standard; {n_library} carry a spectral-library
                name and nothing else. Published data, so the whole experiment below can be re-run by anyone.</p>

              <div class="gx-scale">
                <div class="gx-scale-box"><em>Real analytical run · E4CE Lab</em><b>{N_FEATURES:,}</b>
                  <span>Resolved features, one extract. No identities.</span></div>
                <div class="gx-scale-vs">vs</div>
                <div class="gx-scale-box"><em>Published case study · FCM2018</em><b>{n_assignments}</b>
                  <span>Reported assignments, each with a name and a structure.</span></div>
              </div>
              <p class="gx-small">Two different samples from two different studies, side by side for scale.
                The {n_assignments} were not filtered out of the {N_FEATURES:,}. What the pairing shows is how
                much narrowing sits between an instrument's output and a table a model can be pointed at.</p>

              <div class="gx-layers">
                <div class="gx-layer"><b>Layer 1 · Measurement</b><strong>A signal exists in an analytical run</strong>
                  Baseline, integration window, deconvolution model, and wherever the reporting threshold was set.
                  Change any of them and the number of features changes.
                  <span class="gx-layer-tag">Inherited · not modelled here</span></div>
                <div class="gx-layer"><b>Layer 2 · Identification</b><strong>A signal is assigned a chemical identity</strong>
                  A match against a spectral library, with the molecular formula constrained by mass, and a level
                  of analytical evidence attached to it. For {n_library} of these {n_assignments} entries no standard was ever injected.
                  <span class="gx-layer-tag">Inherited · recorded as the MSI level</span></div>
                <div class="gx-layer"><b>Layer 3 · Model assumption</b><strong>A structure is passed to the model</strong>
                  One formula, many structures. The model never sees the peak or the name — only the structure
                  somebody handed it.
                  <span class="gx-layer-q">What happens downstream when the assumed molecular identity is wrong
                    or weakly supported?</span>
                  <span class="gx-layer-tag">The one this page propagates</span></div>
              </div>
              <p class="gx-small" style="margin-top:10px;font-size:13px;color:#40555c">
                Three assumptions stack before a hazard score exists. This notebook is not re-identifying peaks.
                It takes the third layer and propagates its uncertainty through to the model, and it names the
                first two rather than letting them disappear into the word <i>peak</i>.</p>

              <div class="gx-note warn" style="margin-top:14px">
                <strong>Separate datasets, separate roles.</strong>
                The chromatogram above is a real GC-QTOF migration run, used to illustrate the complexity of
                an analytical run. The identity experiment below uses the {n_assignments} published FCM2018
                assignments curated from Galmán Graíño et al. No identity, model score, weight or conclusion
                anywhere below is calculated from that chromatogram.
              </div>
            </div>'''

        from types import SimpleNamespace
        return SimpleNamespace(
            section=section, n_features=N_FEATURES,
            counts=(N_MAJOR, N_MEDIUM, N_MINOR),
        )

    detection = _build_detection_panel()
    return (detection,)


@app.cell(hide_code=True)
def _(detection, features, mo, provenance):
    mo.Html(detection.section(features, provenance))
    return


